import { MakeLogicType, actions, kea, listeners, path, reducers, selectors } from 'kea'
import { actionToUrl, router, urlToAction } from 'kea-router'
import posthog from 'posthog-js'

import { objectsEqual } from 'lib/utils/objects'

import { BrandedSegmentEnumApi } from 'products/web_analytics/frontend/generated/api.schemas'

import {
    type AiVisibilityDays,
    type AiVisibilityFilterTab,
    type AiVisibilityFilters,
    DEFAULT_AI_VISIBILITY_DAYS,
    filtersFromSearchParams,
    withFilterSearchParams,
} from './aiVisibilityFilters'

